H.background();
const v = H.plot2d({ xMin: 0, xMax: 60, yMin: 0, yMax: 14 });
v.grid(); v.axes();
const Ca = 0.1, Va = 25, Cb = 0.1;
const pKa1 = (P.pKa1 !== undefined ? P.pKa1 : 3.0);
const pKa2 = pKa1 + 5;
const Veq1 = Ca * Va / Cb;
const Veq2 = 2 * Veq1;
function pH(Vb) {
  if (Vb <= 0) return 0.5 * (pKa1 - Math.log10(Ca));
  if (Vb < Veq1) return pKa1 + Math.log10(Vb / (Veq1 - Vb));
  if (Math.abs(Vb - Veq1) < 1e-9) return 0.5 * (pKa1 + pKa2);
  if (Vb < Veq2) return pKa2 + Math.log10((Vb - Veq1) / (Veq2 - Vb));
  if (Math.abs(Vb - Veq2) < 1e-9) return 0.5 * (14 + pKa2);
  const nb = Cb * (Vb - Veq2) / 1000, Vt = (Va + Vb) / 1000;
  return 14 + Math.log10(nb / Vt);
}
v.fn(x => { const y = pH(x); return (isFinite(y) ? Math.max(0.2, Math.min(13.8, y)) : NaN); }, { color: H.colors.accent, width: 3 });
v.dot(Veq1 / 2, pKa1, { r: 6, fill: H.colors.violet });
v.text("pH=pKa1=" + pKa1.toFixed(1), Veq1/2 + 1, pKa1 - 1, { color: H.colors.violet, size: 11 });
v.dot(Veq1 + Veq1 / 2, pKa2, { r: 6, fill: H.colors.violet });
